// Generated by Cypress Author — 2026-04-27
// Tests fonctionnels pour les sections Changelog et Prescriptions admin
describe('Changelog', () => {
    beforeEach(() => {
        cy.login()
    })

    it('Page chargée → titre "Nouveautés & corrections" visible', () => {
        cy.visit('/changelog')
        cy.contains('h1', 'Nouveautés').should('be.visible')
    })

    // Generated by Cypress Author — 2026-10-23
    it('Navigation par version majeure puis mineure → entrées correspondantes visibles', () => {
        cy.visit('/changelog')
        cy.get('#changelog-nav').should('contain.text', '3.x').and('contain.text', '2.x')

        cy.get('#changelog-nav').contains('a', '3.x').click()
        cy.get('#changelog-3-x .changelog-minor-nav').contains('a', '3.0').click()
        cy.get('#changelog-3-x-3-0').should('be.visible').and('contain.text', '3.0.0-rc.4')

        cy.get('#changelog-nav').contains('a', '2.x').click()
        cy.get('#changelog-2-x .changelog-minor-nav').contains('a', '2.10').click()
        cy.get('#changelog-2-x-2-10').should('be.visible').and('contain.text', '2.10.7')
    })
})

describe('Administration — prescriptions', () => {
    beforeEach(() => {
        cy.login()
        cy.visit('/admin/prescriptions')
    })

    it('Page chargée → gestion des prescriptions visible', () => {
        cy.contains('Gestion des prescriptions').should('be.visible')
    })

    it('Navigation prescriptions → textes applicables accessibles', () => {
        cy.visit('/admin/textes-applicables')
        cy.contains('Gestion des textes applicables').should('be.visible')
    })

    it('Navigation prescriptions → articles accessibles', () => {
        cy.visit('/admin/prescriptions/articles/')
        // Page should load without error (status checked via smoke) — verify heading
        cy.get('body').should('not.contain', 'Internal Server Error')
    })
})
